// Private fixture on stdin. Use the built Web application and the real loopback
// user router. No responses are intercepted or generated by the browser test.
import { chromium } from '@playwright/test';
import { preview } from 'vite';
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root=fileURLToPath(new URL('../',import.meta.url));
const tls=resolve(root,'../../.local/tls');
let input='';
for await (const chunk of process.stdin) input+=chunk;
const f=JSON.parse(input);
const upstream=new URL(f.api);
if(upstream.protocol!=='http:'||upstream.hostname!=='127.0.0.1'||!upstream.port ||
    f.origin!=='https://127.0.0.1:43122' || typeof f.token!=='string')throw Error('Expected a private loopback user fixture');
const server=await preview({root,configFile:false,logLevel:'silent',preview:{host:'127.0.0.1',port:43122,strictPort:true,
  https:{key:readFileSync(resolve(tls,'key.pem')),cert:readFileSync(resolve(tls,'cert.pem'))},
  proxy:{'/api/v1/':{target:upstream.origin,changeOrigin:false}}}});
let browser;
try {
  browser=await chromium.launch({channel:'chrome',headless:true});
  const context=await browser.newContext({baseURL:f.origin,ignoreHTTPSErrors:true,viewport:{width:1280,height:960}});
  await context.addCookies([{name:'__Host-orange-user',value:f.token,url:f.origin,secure:true,httpOnly:true,sameSite:'Lax'}]);
  const page=await context.newPage();
  page.setDefaultTimeout(15000);
  const route='/agent/runs/'+encodeURIComponent(f.run)+'/notion';
  await page.goto(route);
  await page.getByRole('combobox',{name:'Notion 来源'}).click();
  await page.locator('.ant-select-item-option-content').filter({hasText:'shared'}).click();
  await page.getByRole('checkbox',{name:'notes · 页面'}).check();
  await page.getByRole('checkbox',{name:'tasks · 数据库'}).check();
  const saved=page.waitForResponse(r=>r.request().method()==='POST'&&new URL(r.url()).pathname.endsWith('/connectors/notion'));
  await page.getByRole('button',{name:'授权所选文档 15 分钟'}).click();
  const receipt=await (await saved).json();
  if(!receipt.grant_id)throw Error('No document grant');
  const section=page.getByRole('region',{name:'文档授权 '+receipt.grant_id});
  await section.getByLabel('页面标题').fill('Shared');
  await section.getByRole('button',{name:'搜索已授权页面'}).click();
  await section.getByRole('button',{name:'Shared notes'}).click();
  await section.getByRole('heading',{name:'Shared notes'}).waitFor();
  await section.getByRole('button',{name:'读取页面内容块'}).click();
  await section.getByText('fixture block contents',{exact:true}).waitFor();
  await section.getByRole('button',{name:'查询 tasks'}).click();
  await section.getByRole('button',{name:'Approved record'}).click();
  await section.getByRole('heading',{name:'Approved record'}).waitFor();
  if(f.screenshot)await page.screenshot({path:f.screenshot,fullPage:true});
  await section.getByRole('button',{name:'撤销文档授权'}).click();
  await section.getByText('已撤销',{exact:true}).waitFor();
  await page.reload();
  await section.getByText('已撤销',{exact:true}).waitFor();
  if(await section.getByRole('heading',{name:'Approved record'}).count())throw Error('Revoked row still visible');
  process.stdout.write(JSON.stringify({searched:true,page:true,blocks:true,database:true,read_scoped_row:true,revoked_after_reload:true})+'\n');
} finally {
  if(browser)await browser.close();
  await server.close();
}
